DECLARE
  CURSOR c_emp IS SELECT employee_id FROM employees
    WHERE department_id = 90;
BEGIN
  FOR r IN c_emp LOOP
    UPDATE employees SET bonus = bonus + 100
    WHERE employee_id = r.employee_id;
  END LOOP;
END;
/

TYPE t_id_list IS TABLE OF employees.employee_id%TYPE;
v_ids t_id_list;

SELECT employee_id
BULK COLLECT INTO v_ids
FROM employees WHERE department_id = 90;

FORALL i IN v_ids.FIRST .. v_ids.LAST
  UPDATE employees SET bonus = bonus + 100
  WHERE employee_id = v_ids(i);

COMMIT;

-- The anti-pattern BULK COLLECT + FORALL fixes:
FOR r IN (SELECT employee_id FROM employees
          WHERE department_id = 90) LOOP
  UPDATE employees SET bonus = bonus + 100
  WHERE employee_id = r.employee_id;
END LOOP;
